## solutions

#### iterative

```cpp
Node* zipperLists(Node* head1, Node* head2) {
  Node* head = head1;
  Node* tail = head;

  Node* current1 = head1->next;
  Node* current2 = head2;

  int count = 1;
  while (current1 != nullptr && current2 != nullptr) {
    if (count % 2 == 0) {
      tail->next = current1;
      current1 = current1->next;
    } else {
      tail->next = current2;
      current2 = current2->next;
    }

    tail = tail->next;
    count += 1;
  }

  if (current1 != nullptr) {
    tail->next = current1;
  }
  if (current2 != nullptr) {
    tail->next = current2;
  }

  return head;
}
```

- n = length of list 1
- m = length of list 2
- Time: O(min(n, m))
- Space: O(1)

#### recursive

```cpp
Node* zipperLists(Node* head1, Node* head2) {
  if (head1 == nullptr) {
    return head2;
  }

  if (head2 == nullptr) {
    return head1;
  }

  head2->next = zipperLists(head1->next, head2->next);
  head1->next = head2;
  return head1;
}
```

- n = length of list 1
- m = length of list 2
- Time: O(min(n, m))
- Space: O(min(n, m))
